#include <iostream>
#include <string>
using namespace std;

// 判断是否为低位形态（小写字母）
bool isLower(char c) {
    return c >= 'a' && c <= 'z';
}

// 形态翻转
char flip(char c) {
    if (isLower(c)) return char(c - ('a' - 'A')); // 低位变高位
    else return char(c + ('a' - 'A'));            // 高位变低位
}

// 同形态后移一位，循环
char nextSameCase(char c) {
    if (isLower(c)) {
        return (c == 'z') ? 'a' : char(c + 1);
    } else {
        return (c == 'Z') ? 'A' : char(c + 1);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n;
    cin >> s;

    string ans;
    ans.reserve(n);

    for (int i = 0; i < n; ++i) {
        char c = s[i];
        if (i == 0) {
            ans.push_back(flip(c));          // 首个字符翻转
        } else {
            char prev = s[i - 1];            // 原串前一字符
            bool diff = (isLower(c) != isLower(prev));
            if (diff) {
                ans.push_back(flip(c));
            } else {
                ans.push_back(nextSameCase(c));
            }
        }
    }

    cout << ans << "\n";
    return 0;
}
